    private void btnSimpanActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnSimpanActionPerformed
        // TODO add your handling code here:
        // 1. Ambil data dari form
    String nim = txtNIM.getText().trim();
    String nama = txtNama.getText().trim();
    String prodi = txtProdi.getText().trim();
    String noHp = txtNoHp.getText().trim();
    String email = txtEmail.getText().trim();

    // 2. Ambil jenis kelamin
    String jenisKelamin = "";

    if (rbLaki.isSelected()) {
        jenisKelamin = "L";
    } else if (rbPerempuan.isSelected()) {
        jenisKelamin = "P";
    }

    // 3. Validasi data wajib
    if (nim.isEmpty() || nama.isEmpty()
            || prodi.isEmpty() || jenisKelamin.isEmpty()) {

        javax.swing.JOptionPane.showMessageDialog(
                this,
                "NIM, Nama, Prodi, dan Jenis Kelamin wajib diisi!",
                "Peringatan",
                javax.swing.JOptionPane.WARNING_MESSAGE
        );
        return;
    }

    // 4. Simpan data ke database
    try {
        model.Peserta peserta = new model.Peserta(
                nim,
                nama,
                jenisKelamin,
                prodi,
                noHp,
                email
        );

        dao.PesertaDao daoPeserta = new dao.PesertaDao();

        boolean berhasil = daoPeserta.insert(peserta);

        if (berhasil) {

            javax.swing.JOptionPane.showMessageDialog(
                    this,
                    "Data peserta berhasil disimpan!",
                    "Sukses",
                    javax.swing.JOptionPane.INFORMATION_MESSAGE
            );

            // 5. Kosongkan form setelah berhasil
            txtNIM.setText("");
            txtNama.setText("");
            txtProdi.setText("");
            txtNoHp.setText("");
            txtEmail.setText("");

            rbLaki.setSelected(false);
            rbPerempuan.setSelected(false);

            // Fokus kembali ke kolom NIM
            txtNIM.requestFocus();

        } else {

            javax.swing.JOptionPane.showMessageDialog(
                    this,
                    "Data peserta gagal disimpan!",
                    "Gagal",
                    javax.swing.JOptionPane.ERROR_MESSAGE
            );
        }

    } catch (java.sql.SQLException e) {

        javax.swing.JOptionPane.showMessageDialog(
                this,
                "Gagal menyimpan data ke database:\n" + e.getMessage(),
                "Error Database",
                javax.swing.JOptionPane.ERROR_MESSAGE
        );

    } catch (IllegalArgumentException e) {

        javax.swing.JOptionPane.showMessageDialog(
                this,
                e.getMessage(),
                "Data Tidak Valid",
                javax.swing.JOptionPane.WARNING_MESSAGE
        );
    }
    }//GEN-LAST:event_btnSimpanActionPerformed

